export default async function next(
  {
    submissionId,
    title,
    location,
    date,
    prompt,
    templateId,
    channelId,
    relayUrl,
    acknowledge,
    resolution,
    confirmedUrl,
  },
  ctx,
) {
  if (
    !submissionId ||
    !title ||
    !location ||
    !date ||
    !prompt ||
    !templateId ||
    !channelId ||
    !/^https:\/\//.test(relayUrl)
  )
    throw Error("Enter event details, unique submission ID, template, channel and relay URL");
  const key = "event-banner:" + submissionId,
    event = { title, location, date, prompt, templateId, channelId };
  let state = await ctx.state.get(key);
  if (!state) {
    state = { event, phase: "generate", pending: null };
    await ctx.state.set(key, state);
  } else if (JSON.stringify(state.event) !== JSON.stringify(event))
    throw Error("Submission ID already belongs to different event details");
  if (state.pending) {
    if (acknowledge !== state.pending || !["confirmed", "absent"].includes(resolution))
      throw Error("Inspect unknown write " + state.pending);
    if (resolution === "confirmed") {
      if (state.phase === "generate") {
        if (!/^https:\/\//.test(confirmedUrl)) throw Error("Enter generated image URL");
        state.generatedUrl = confirmedUrl;
        state.phase = "upload";
      } else if (state.phase === "upload") {
        if (!/^https:\/\//.test(confirmedUrl)) throw Error("Enter Cloudinary URL");
        state.uploadUrl = confirmedUrl;
        state.phase = "render";
      } else if (state.phase === "render") {
        if (!/^https:\/\//.test(confirmedUrl)) throw Error("Enter completed banner URL");
        state.bannerUrl = confirmedUrl;
        state.phase = "send";
      } else state.phase = "done";
    }
    state.pending = null;
    await ctx.state.set(key, state);
  }
  const phase = state.phase;
  if (phase !== "done") {
    state.pending = phase + ":" + submissionId;
    await ctx.state.set(key, state);
  }
  const mods = [
      { name: "placeholder_image", image_url: state.uploadUrl || "https://example.test/image.png" },
      { name: "placeholder_text", text: title },
      { name: "placeholder_location", text: location },
      { name: "placeholder_date", text: date },
    ],
    content =
      "📅 New Event Alert!  " +
      title +
      " being held at  " +
      location +
      " on the  " +
      date +
      "! Don’t miss it!";
  return {
    key,
    phase,
    prompt,
    templateId,
    generatedUrl: state.generatedUrl || "https://example.test/image.png",
    modifications: mods,
    relayUrl,
    relayBody: {
      submissionId,
      channelId,
      imageUrl: state.bannerUrl || "https://example.test/banner.jpg",
      content,
    },
  };
}

